"""Version ranges (docs/ranges.md)."""

import re

from pinset.errors import RangeError, VersionError
from pinset.version import BUILD_RE, PRERELEASE_RE, Version

OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")
WILD = ("x", "X", "*")
NUM_RE = re.compile(r"0|[1-9][0-9]*")
SPACES = " \t"
SPLIT_RE = re.compile(r"[ \t]+")


def _low(major, minor, patch):
    """Lower than every version of the release (docs/ranges.md, section 4)."""
    return Version(major, minor, patch, ("0",))


class _Partial:
    def __init__(self, nums, pre, build):
        self.nums = nums  # list of ints or None (wildcard), always length 3
        self.pre = pre
        self.build = build

    @property
    def full(self):
        return all(n is not None for n in self.nums)

    def version(self):
        """Full version (zeros fill wildcards)."""
        n = [0 if x is None else x for x in self.nums]
        return Version(n[0], n[1], n[2], self.pre)

    def given(self):
        return sum(1 for n in self.nums if n is not None)

    def next_block(self):
        """Lowest bound just above the block: lower-than-everything of the next release."""
        a, b, c = self.nums
        if b is None:
            return (a + 1, 0, 0)
        if c is None:
            return (a, b + 1, 0)
        return (a, b, c + 1)

    def block_end(self):
        """Exclusive upper bound of the block named (partial only)."""
        return _low(*self.next_block())


def _parse_partial(text):
    m = re.search(r"[-+]", text)
    core, rest = (text, "") if m is None else (text[: m.start()], text[m.start():])
    parts = core.split(".")
    if len(parts) > 3:
        raise RangeError("bad-version", f"too many parts in {text!r}")
    nums = []
    seen_wild = False
    for part in parts:
        if part in WILD:
            seen_wild = True
            nums.append(None)
        elif NUM_RE.fullmatch(part):
            if seen_wild:
                raise RangeError("bad-version", f"number after wildcard in {text!r}")
            nums.append(int(part))
        else:
            raise RangeError("bad-version", f"bad part {part!r} in {text!r}")
    pre = build = ()
    if rest:
        if len(parts) != 3 or seen_wild:
            raise RangeError("bad-version", f"prerelease or build on a partial version {text!r}")
        if rest[0] == "-":
            pr, plus, b = rest[1:].partition("+")
            if not PRERELEASE_RE.fullmatch(pr):
                raise RangeError("bad-version", f"bad prerelease in {text!r}")
            pre = tuple(pr.split("."))
        else:
            plus, b = "+", rest[1:]
            if False:
                pass
        if plus:
            if not BUILD_RE.fullmatch(b):
                raise RangeError("bad-version", f"bad build in {text!r}")
            build = tuple(b.split("."))
    nums += [None] * (3 - len(nums))
    return _Partial(nums, pre, build)


# A bound is (op, Version, carries) with op in ">=", ">", "<", "<=", "=".
# An alternative is a list of bounds, or None for "no version".

def _comparator(op, p):
    carries = bool(p.pre)
    if p.nums[0] is None:
        if op in ("", "=", ">=", "<=", "^", "~"):
            return []
        return None  # < or >
    full = p.full
    v = p.version()
    if op in ("", "="):
        if full:
            return [("=", v, carries)]
        return [(">=", v, False), ("<", p.block_end(), False)]
    if op == ">":
        if full:
            return [(">", v, carries)]
        return [(">=", Version(*p.next_block()), False)]
    if op == ">=":
        return [(">=", v, carries)]
    if op == "<":
        if full:
            return [("<", v, carries)]
        return [("<", _low(*(n or 0 for n in p.nums)), False)]
    if op == "<=":
        if full:
            return [("<=", v, carries)]
        return [("<", p.block_end(), False)]
    a, b, c = p.nums
    if op == "~":
        if b is None:
            hi = _low(a + 1, 0, 0)
        else:
            hi = _low(a, b + 1, 0)
    else:  # caret
        if a != 0 or b is None:
            hi = _low(a + 1, 0, 0)
        elif b != 0:
            hi = _low(0, b + 1, 0)
        elif c is None:
            hi = _low(0, 1, 0)
        else:
            hi = _low(0, 0, c + 1)
    return [(">=", v, carries), ("<", hi, False)]


def _hyphen(lo, hi):
    out = []
    if lo.nums[0] is not None:
        out.append((">=", lo.version(), bool(lo.pre)))
    if hi.nums[0] is not None:
        if hi.full:
            out.append(("<=", hi.version(), bool(hi.pre)))
        else:
            out.append(("<", hi.block_end(), False))
    return out


def _holds(op, bound, v):
    if op == "=":
        return v == bound
    if op == ">=":
        return v >= bound
    if op == ">":
        return v > bound
    if op == "<":
        return v < bound
    return v <= bound


class Range:
    def __init__(self, text, alternatives, exact):
        self.text = text
        self._alts = alternatives
        self._exact = exact

    def test(self, version: Version) -> bool:
        """True when `version` satisfies the range."""
        for alt in self._alts:
            if alt is None:
                continue
            if not all(_holds(op, b, version) for op, b, _ in alt):
                continue
            if version.is_prerelease() and not any(
                c and b.release == version.release for _, b, c in alt
            ):
                continue
            return True
        return False

    def is_exact(self) -> bool:
        """True for a range that names one version (docs/ranges.md, section 10)."""
        return self._exact

    def __str__(self):
        return self.text


def parse_range(text: str) -> Range:
    if not isinstance(text, str):
        raise RangeError("bad-range", f"a range is a string, not {type(text).__name__}")
    if not text.strip(SPACES):
        raise RangeError("bad-range", "empty range")
    raw_alts = text.split("||")
    for a in raw_alts:
        if not a.strip(SPACES):
            raise RangeError("bad-range", "empty alternative")
    shaped = []  # ("hyphen", lo, hi) or ("set", [(op, text)])
    for a in raw_alts:
        tokens = SPLIT_RE.split(a.strip(SPACES))
        if "-" in tokens:
            if len(tokens) != 3 or tokens[1] != "-":
                raise RangeError("bad-range", f"misplaced '-' in {a!r}")
            for t in (tokens[0], tokens[2]):
                if not (t[0] in "0123456789" or t[0] in WILD):
                    raise RangeError("bad-range", f"bad hyphen range end {t!r}")
            shaped.append(("hyphen", tokens[0], tokens[2]))
            continue
        items = []
        for t in tokens:
            op = next((o for o in OPERATORS if t.startswith(o)), "")
            rest = t[len(op):]
            if not rest or not (rest[0] in "0123456789" or rest[0] in WILD):
                raise RangeError("bad-range", f"bad token {t!r}")
            items.append((op, rest))
        shaped.append(("set", items))
    alts = []
    for s in shaped:
        if s[0] == "hyphen":
            alts.append(_hyphen(_parse_partial(s[1]), _parse_partial(s[2])))
            continue
        bounds = []
        impossible = False
        for op, rest in s[1]:
            b = _comparator(op, _parse_partial(rest))
            if b is None:
                impossible = True
            else:
                bounds.extend(b)
        alts.append(None if impossible else bounds)
    exact = False
    if len(shaped) == 1 and shaped[0][0] == "set" and len(shaped[0][1]) == 1:
        op, rest = shaped[0][1][0]
        if op in ("", "="):
            exact = _parse_partial(rest).full
    return Range(text, alts, exact)
