assert t(">=1.2.3-beta.2 <1.3.0","1.2.3-rc.1") and not t(">=1.2.3-beta.2 <1.3.0","1.2.5-rc.1")
assert t("* || =2.0.0-rc.1","2.0.0-rc.1") and not t("*","1.0.0-rc.1")
assert not t("<1.3.0","1.3.0-rc.1") and not t("<*","1.0.0") and t("<=*","1.0.0")
